B.aWB=new A.aM(B.bU,B.aEV,"Horno a 220 \xb0C. Ten el caldo caliente.","No queda caldo, el arroz est\xe1 tierno y por arriba se ha dorado (unos 20 minutos de horno).",B.ajP,B.apy,B.aFC,null,null,B.C)
B.ap5=s(["Olla","Sart\xe9n","Horno (opcional, para gratinar)"],t.s)
