B.aqS=s(["Chorizo \u2192 bacon o carne picada."],t.s)
B.aY7=new A.aM(B.H,B.ap5,null,"Pasta al dente y salsa bien caliente; si gratinas, el queso dorado (5 minutos).",B.alL,B.r,B.aqS,null,null,B.C)
B.ail=s(["Fuente de horno","Sart\xe9n","Horno"],t.s)
B.ajU=s(["Capas: un poco de salsa en el fondo, placas, carne, bechamel\u2026 y termina con bechamel y queso.","D\xe9jala reposar 10 minutos antes de cortar: as\xed no se desmorona."],t.s)
